import type {
  EvidenceKind,
  EvidenceStrength,
  ToolInput,
  ToolName,
  UntrustedContent,
} from "@campaign-sentinel/contracts";
import type { Investigation } from "../ledger/ledger.service";

/** Evidence a tool produces; the executor stores it, assigns refs (E1…) and provenance. */
export interface EvidenceDraft {
  kind: EvidenceKind;
  strength: EvidenceStrength;
  /** generated by code, contains the numbers */
  statement: string;
  data: unknown;
}

export interface ToolOutput {
  data: unknown;
  evidence?: EvidenceDraft[];
  warnings?: string[];
  untrustedContent?: UntrustedContent;
}

export interface ToolContext {
  investigation: Investigation;
  /** aborted when the call times out */
  signal: AbortSignal;
}

/** One tool implementation. The executor validates `input` against the contracts schema before `run`. */
export interface ToolHandler<N extends ToolName = ToolName> {
  name: N;
  /** default 5 000 ms (spec §5.3) */
  timeoutMs?: number;
  run(input: ToolInput<N>, ctx: ToolContext): Promise<ToolOutput>;
}

/** A tool failure the agent should see as `{ ok: false, error }`. Transient codes are retried once. */
export class ToolFailure extends Error {
  constructor(
    readonly code: string,
    message: string,
    readonly retryable = false,
  ) {
    super(message);
    this.name = "ToolFailure";
  }
}
